  <script>
    (() => {
      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
      const scene = document.querySelector('.scene');
      const layers = [...document.querySelectorAll('.pointer-layer')];
      if (reduceMotion.matches || !('PointerEvent' in window)) return;

      let targetX = 0;
      let targetY = 0;
      let currentX = 0;
      let currentY = 0;
      let frame = 0;

      function move(event) {
        const bounds = scene.getBoundingClientRect();
        targetX = ((event.clientX - bounds.left) / bounds.width - .5) * 2;
        targetY = ((event.clientY - bounds.top) / bounds.height - .5) * 2;
        if (!frame) frame = requestAnimationFrame(update);
      }

      function update() {
        currentX += (targetX - currentX) * .075;
        currentY += (targetY - currentY) * .075;
        layers.forEach((layer, index) => {
          const depth = index === 0 ? 1.15 : index === 1 ? .65 : .35;
          layer.style.transform = `translate(${currentX * 7 * depth}px, ${currentY * 5 * depth}px)`;
        });
        if (Math.abs(targetX - currentX) + Math.abs(targetY - currentY) > .002) {
          frame = requestAnimationFrame(update);
        } else {
          frame = 0;
        }
      }

      scene.addEventListener('pointermove', move, { passive: true });
      scene.addEventListener('pointerleave', () => {
        targetX = 0;
        targetY = 0;
        if (!frame) frame = requestAnimationFrame(update);
      }, { passive: true });
    })();
  </script>
